{
  "name": "collection-of-interactive-animations",
  "private": true,
  "version": "0.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "react": "^19.2.4",
    "react-dom": "^19.2.4",
    "three": "^0.182.0"
  },
  "devDependencies": {
    "@types/node": "^22.14.0",
    "@vitejs/plugin-react": "^5.0.0",
    "typescript": "~5.8.2",
    "vite": "^6.2.0"
  }
}

import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { MeshSurfaceSampler } from 'three/addons/math/MeshSurfaceSampler.js';

interface ThreeSceneProps {
  width: number;
  height: number;
}

const ThreeScene: React.FC<ThreeSceneProps> = ({ width, height }) => {
  const mountRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!mountRef.current) return;

    // --- SCENE SETUP ---
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x020205, 0.02); // Match bg color

    const camera = new THREE.PerspectiveCamera(75, width / height, 0.1, 1000);
    camera.position.z = 30;
    camera.position.y = 5;

    const renderer = new THREE.WebGLRenderer({ 
      alpha: true, 
      antialias: true,
      powerPreference: "high-performance"
    });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    mountRef.current.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 0.5;

    // --- LIGHTING ---
    const ambientLight = new THREE.AmbientLight(0x404040, 2);
    scene.add(ambientLight);

    const centerLight = new THREE.PointLight(0x00ffff, 5, 50);
    scene.add(centerLight);

    const purpleLight = new THREE.PointLight(0xaa00ff, 3, 50);
    purpleLight.position.set(10, 10, 10);
    scene.add(purpleLight);

    // --- PARTICLES SETUP ---
    const PARTICLE_COUNT = 8000;
    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(PARTICLE_COUNT * 3);
    const targets = new Float32Array(PARTICLE_COUNT * 3); // Home positions
    const velocities = new Float32Array(PARTICLE_COUNT * 3);
    const colors = new Float32Array(PARTICLE_COUNT * 3);
    const randomness = new Float32Array(PARTICLE_COUNT);

    // INITIALIZATION: Fill with random sphere data so we see something immediately
    const color1 = new THREE.Color(0x00ffff);
    const color2 = new THREE.Color(0xaa00ff);

    for (let i = 0; i < PARTICLE_COUNT; i++) {
        const r = 15 + Math.random() * 15;
        const theta = Math.random() * Math.PI * 2;
        const phi = Math.acos(2 * Math.random() - 1);

        const x = r * Math.sin(phi) * Math.cos(theta);
        const y = r * Math.sin(phi) * Math.sin(theta);
        const z = r * Math.cos(phi);

        positions[i * 3] = x;
        positions[i * 3 + 1] = y;
        positions[i * 3 + 2] = z;

        // Default targets are same as start until loaded
        targets[i * 3] = x;
        targets[i * 3 + 1] = y;
        targets[i * 3 + 2] = z;

        // Init Colors
        const alpha = Math.random();
        const c = color1.clone().lerp(color2, alpha);
        colors[i * 3] = c.r;
        colors[i * 3 + 1] = c.g;
        colors[i * 3 + 2] = c.b;

        randomness[i] = Math.random();
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    // Texture generation
    const getTexture = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 32;
        canvas.height = 32;
        const ctx = canvas.getContext('2d');
        if(ctx) {
            const grad = ctx.createRadialGradient(16, 16, 0, 16, 16, 16);
            grad.addColorStop(0, 'rgba(255, 255, 255, 1)');
            grad.addColorStop(0.2, 'rgba(200, 255, 255, 0.8)');
            grad.addColorStop(0.5, 'rgba(0, 255, 255, 0.2)');
            grad.addColorStop(1, 'rgba(0, 0, 0, 0)');
            ctx.fillStyle = grad;
            ctx.fillRect(0, 0, 32, 32);
        }
        const texture = new THREE.CanvasTexture(canvas);
        return texture;
    };

    const material = new THREE.PointsMaterial({
        size: 0.35,
        map: getTexture(),
        transparent: true,
        opacity: 0.9,
        vertexColors: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
    });

    const particles = new THREE.Points(geometry, material);
    scene.add(particles);

    // --- CORE GEM ---
    const coreGeo = new THREE.IcosahedronGeometry(1.5, 0);
    const coreMat = new THREE.MeshPhysicalMaterial({
        color: 0x00ffff,
        emissive: 0x0044ff,
        emissiveIntensity: 2,
        roughness: 0.1,
        metalness: 0.9,
        transparent: true,
        opacity: 0.9,
        transmission: 0.2,
        thickness: 1.0,
    });
    const coreMesh = new THREE.Mesh(coreGeo, coreMat);
    scene.add(coreMesh);

    // Halo
    const haloGeo = new THREE.PlaneGeometry(15, 15);
    const haloMat = new THREE.MeshBasicMaterial({
        map: getTexture(),
        color: 0x00ffff,
        transparent: true,
        opacity: 0.4,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide
    });
    const haloMesh = new THREE.Mesh(haloGeo, haloMat);
    scene.add(haloMesh);

    // --- GLB LOADER ---
    const loader = new GLTFLoader();
    loader.load('3834385f-f829-4a28-8dfd-e9125e9cb138.glb', (gltf) => {
        const meshes: THREE.Mesh[] = [];
        gltf.scene.traverse((child) => {
            if ((child as THREE.Mesh).isMesh) {
                meshes.push(child as THREE.Mesh);
            }
        });

        if (meshes.length > 0) {
            let pIndex = 0;
            const tempPos = new THREE.Vector3();
            const tempNormal = new THREE.Vector3();
            // Just assume one main mesh or iterate cycling
            const mesh = meshes[0];
            const sampler = new MeshSurfaceSampler(mesh).build();
            const matrix = mesh.matrixWorld; // usually identity if not in scene graph root, but good to check

            for (let i = 0; i < PARTICLE_COUNT; i++) {
                sampler.sample(tempPos, tempNormal);
                // No matrix apply needed if we don't add mesh to scene, but if GLB has transforms:
                // Since we traverse, child.matrixWorld might be local. 
                // Let's assume the mesh geometry is what we want.

                const SCALE = 15.0;
                targets[i * 3] = tempPos.x * SCALE;
                targets[i * 3 + 1] = tempPos.y * SCALE;
                targets[i * 3 + 2] = tempPos.z * SCALE;

                // Update color based on new shape (optional, but looks nice)
                const dist = tempPos.length();
                const a = Math.min(1, dist * 2 + 0.2); 
                const c = color1.clone().lerp(color2, a);
                colors[i * 3] = c.r;
                colors[i * 3 + 1] = c.g;
                colors[i * 3 + 2] = c.b;
            }

            // IMPORTANT: Flag colors for update
            geometry.attributes.color.needsUpdate = true;
        }
    }, 
    undefined, 
    (error) => {
        console.error("Failed to load GLB, using default sphere:", error);
    });

    // --- MOUSE INTERACTION ---
    const mouse = new THREE.Vector2();
    const raycaster = new THREE.Raycaster();
    const plane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
    const mouseParams = { x: 9999, y: 9999, active: false };

    const handleMouseMove = (event: MouseEvent) => {
        const rect = mountRef.current?.getBoundingClientRect();
        if (!rect) return;
        mouse.x = ((event.clientX - rect.left) / width) * 2 - 1;
        mouse.y = -((event.clientY - rect.top) / height) * 2 + 1;
        mouseParams.active = true;
    };

    // --- ANIMATION LOOP ---
    const clock = new THREE.Clock();
    let frameId: number;

    const animate = () => {
        frameId = requestAnimationFrame(animate);
        const time = clock.getElapsedTime();

        controls.update();

        // Raycasting
        raycaster.setFromCamera(mouse, camera);
        const intersect = new THREE.Vector3();
        raycaster.ray.intersectPlane(plane, intersect);

        // Physics
        for (let i = 0; i < PARTICLE_COUNT; i++) {
            const ix = i * 3;
            const iy = i * 3 + 1;
            const iz = i * 3 + 2;

            let px = positions[ix];
            let py = positions[iy];
            let pz = positions[iz];

            const tx = targets[ix];
            const ty = targets[iy];
            const tz = targets[iz];

            let vx = velocities[ix];
            let vy = velocities[iy];
            let vz = velocities[iz];

            // Spring
            vx += (tx - px) * 0.03;
            vy += (ty - py) * 0.03;
            vz += (tz - pz) * 0.03;

            // Noise
            const rnd = randomness[i];
            const nAmp = 0.02;
            vx += Math.sin(time * 2 + py * 0.5 + rnd * 10) * nAmp;
            vy += Math.cos(time * 1.5 + px * 0.5 + rnd * 10) * nAmp;
            vz += Math.sin(time * 2.2 + pz * 0.5 + rnd * 10) * nAmp;

            // Mouse Repulsion
            if (mouseParams.active) {
                const dx = px - intersect.x;
                const dy = py - intersect.y;
                const dz = pz - intersect.z;
                const distSq = dx*dx + dy*dy + dz*dz;
                const radSq = 600.0; // 25^2 approx
                if (distSq < radSq) {
                    const f = (radSq - distSq) / radSq;
                    const rep = 1.0;
                    vx += dx * f * rep;
                    vy += dy * f * rep;
                    vz += dz * f * rep;
                }
            }

            vx *= 0.92;
            vy *= 0.92;
            vz *= 0.92;

            positions[ix] += vx;
            positions[iy] += vy;
            positions[iz] += vz;

            velocities[ix] = vx;
            velocities[iy] = vy;
            velocities[iz] = vz;
        }

        geometry.attributes.position.needsUpdate = true;

        // Core visual update
        const pulse = 1 + Math.sin(time * 2.5) * 0.1;
        coreMesh.scale.set(pulse, pulse, pulse);
        coreMesh.rotation.y += 0.01;
        coreMesh.rotation.z += 0.005;

        haloMesh.lookAt(camera.position);

        renderer.render(scene, camera);
    };

    window.addEventListener('mousemove', handleMouseMove);
    animate();

    return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        cancelAnimationFrame(frameId);
        if (mountRef.current && renderer.domElement) {
             mountRef.current.removeChild(renderer.domElement);
        }
        controls.dispose();
        geometry.dispose();
        material.dispose();
        renderer.dispose();
    };
  }, [width, height]);

  return <div ref={mountRef} />;
};

export default ThreeScene;

export interface Point3D {
  x: number;
  y: number;
  z: number;
  char?: string; // Specific character override
  brightnessOffset?: number; // 0-1
  isCore?: boolean;
}

export interface ProjectedPoint {
  x: number;
  y: number;
  z: number; // Depth for sorting
  char: string;
  color: string;
  size: number;
  alpha: number;
}

