import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

interface SceneProps {
  width: number;
  height: number;
}

const SceneChaos: React.FC<SceneProps> = ({ width, height }) => {
  const mountRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!mountRef.current) return;

    // --- SETUP ---
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x000000, 0.01);

    const camera = new THREE.PerspectiveCamera(75, width / height, 0.1, 1000);
    camera.position.set(0, 0, 70);

    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 1.0;

    // --- MATH: LORENZ ATTRACTOR ---
    const PARTICLE_COUNT = 10000;
    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(PARTICLE_COUNT * 3);
    const colors = new Float32Array(PARTICLE_COUNT * 3);

    // We store the "current" mathematical state of each particle independent of its 3D position
    // so it can flow along the curve
    const states = new Float32Array(PARTICLE_COUNT * 3); // x, y, z state

    const c1 = new THREE.Color(0xffd700); // Gold
    const c2 = new THREE.Color(0x0000ff); // Blue

    for (let i = 0; i < PARTICLE_COUNT; i++) {
        // Initialize random spots near origin
        let x = (Math.random() - 0.5) * 10;
        let y = (Math.random() - 0.5) * 10;
        let z = (Math.random() - 0.5) * 10 + 25; // Shift z up a bit for lorenz center

        // Pre-simulate to spread them out along the attractor
        const dt = 0.005;
        const sigma = 10;
        const rho = 28;
        const beta = 8/3;

        // Advance random amount of steps
        const steps = Math.random() * 2000;
        for(let s=0; s<steps; s++) {
            const dx = sigma * (y - x) * dt;
            const dy = (x * (rho - z) - y) * dt;
            const dz = (x * y - beta * z) * dt;
            x += dx;
            y += dy;
            z += dz;
        }

        states[i*3] = x;
        states[i*3+1] = y;
        states[i*3+2] = z;

        positions[i*3] = x;
        positions[i*3+1] = y;
        positions[i*3+2] = z;

        colors[i*3] = 1;
        colors[i*3+1] = 1;
        colors[i*3+2] = 1;
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    const getTexture = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 32;
        canvas.height = 32;
        const ctx = canvas.getContext('2d');
        if(ctx) {
            ctx.fillStyle = '#ffffff';
            ctx.beginPath();
            ctx.arc(16, 16, 10, 0, Math.PI * 2);
            ctx.fill();
        }
        return new THREE.CanvasTexture(canvas);
    };

    const material = new THREE.PointsMaterial({
        size: 0.4,
        map: getTexture(),
        transparent: true,
        opacity: 0.7,
        vertexColors: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
    });

    const particles = new THREE.Points(geometry, material);
    scene.add(particles);

    // --- MOUSE ---
    const mouse = new THREE.Vector2();
    const raycaster = new THREE.Raycaster();
    const plane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
    const mouseParams = { active: false };

    const handleMouseMove = (event: MouseEvent) => {
        const rect = mountRef.current?.getBoundingClientRect();
        if (!rect) return;
        mouse.x = ((event.clientX - rect.left) / width) * 2 - 1;
        mouse.y = -((event.clientY - rect.top) / height) * 2 + 1;
        mouseParams.active = true;
    };

    // --- ANIMATION ---
    const clock = new THREE.Clock();
    let frameId: number;

    // Lorenz Constants
    let sigma = 10;
    let rho = 28;
    let beta = 8/3;

    const animate = () => {
        frameId = requestAnimationFrame(animate);
        // We use small fixed time step for stability of differential equation
        const dt = 0.008; 

        controls.update();

        // Mouse Interactivity: Modify Constants
        if (mouseParams.active) {
            // Map mouse X to Rho (Chaos factor)
            // Normal rho is 28. Let's vary from 10 to 50
            const targetRho = 28 + mouse.x * 20;
            rho += (targetRho - rho) * 0.1; // Smooth transition

            // Map mouse Y to Beta
            // Normal beta is 2.66. Vary from 1 to 5
            const targetBeta = 8/3 + mouse.y * 2;
            beta += (targetBeta - beta) * 0.1;
        } else {
            // Reset
            rho += (28 - rho) * 0.05;
            beta += (8/3 - beta) * 0.05;
        }

        const positions = geometry.attributes.position.array as Float32Array;
        const colors = geometry.attributes.color.array as Float32Array;
        const s = states;

        // Center visual offset
        const centerY = 25; 

        for (let i = 0; i < PARTICLE_COUNT; i++) {
            const ix = i * 3;
            let x = s[ix];
            let y = s[ix+1];
            let z = s[ix+2];

            // Update Math
            const dx = sigma * (y - x) * dt;
            const dy = (x * (rho - z) - y) * dt;
            const dz = (x * y - beta * z) * dt;

            x += dx;
            y += dy;
            z += dz;

            s[ix] = x;
            s[ix+1] = y;
            s[ix+2] = z;

            // Visual Update
            positions[ix] = x;
            positions[ix+1] = y;
            positions[ix+2] = z - centerY; // center it vertically in camera

            // Color based on velocity/change
            const vel = Math.sqrt(dx*dx + dy*dy + dz*dz) * 100; // rough speed
            // Map speed to Gold -> Blue
            // Low speed = Blue, High speed = Gold
            const t = Math.min(1, vel * 0.2);
            const c = c2.clone().lerp(c1, t);

            colors[ix] = c.r;
            colors[ix+1] = c.g;
            colors[ix+2] = c.b;
        }

        geometry.attributes.position.needsUpdate = true;
        geometry.attributes.color.needsUpdate = true;

        renderer.render(scene, camera);
    };

    window.addEventListener('mousemove', handleMouseMove);
    animate();

    return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        cancelAnimationFrame(frameId);
        if (mountRef.current && renderer.domElement) {
             mountRef.current.removeChild(renderer.domElement);
        }
        controls.dispose();
        geometry.dispose();
        material.dispose();
        renderer.dispose();
    };
  }, [width, height]);

  return <div ref={mountRef} />;
};

export default SceneChaos;

import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

interface SceneProps {
  width: number;
  height: number;
}

const SceneHyper: React.FC<SceneProps> = ({ width, height }) => {
  const mountRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!mountRef.current) return;

    // --- SETUP ---
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x000000, 0.02);

    const camera = new THREE.PerspectiveCamera(75, width / height, 0.1, 1000);
    camera.position.set(0, 0, 35);

    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 0.5;

    // --- 4D GEOMETRY ---
    const PARTICLES_PER_EDGE = 300;
    const EDGE_COUNT = 32;
    const PARTICLE_COUNT = PARTICLES_PER_EDGE * EDGE_COUNT;

    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(PARTICLE_COUNT * 3);
    const colors = new Float32Array(PARTICLE_COUNT * 3);
    // Base 4D coordinates
    const coords4D = new Float32Array(PARTICLE_COUNT * 4); 

    // Tesseract Vertices (+-1, +-1, +-1, +-1)
    const vertices4D: number[][] = [];
    for(let i=0; i<16; i++) {
        const x = (i & 1) ? 1 : -1;
        const y = (i & 2) ? 1 : -1;
        const z = (i & 4) ? 1 : -1;
        const w = (i & 8) ? 1 : -1;
        vertices4D.push([x, y, z, w]);
    }

    // Edges
    const edges: number[][] = [];
    for(let i=0; i<16; i++) {
        for(let j=i+1; j<16; j++) {
            let diff = 0;
            for(let k=0; k<4; k++) if(vertices4D[i][k] !== vertices4D[j][k]) diff++;
            if(diff === 1) edges.push([i, j]);
        }
    }

    let pIdx = 0;
    const c1 = new THREE.Color(0xff00ff); // Magenta
    const c2 = new THREE.Color(0x00ffff); // Cyan
    const c3 = new THREE.Color(0xffffff); // White highlight

    edges.forEach(edge => {
        const v1 = vertices4D[edge[0]];
        const v2 = vertices4D[edge[1]];

        for(let i=0; i<PARTICLES_PER_EDGE; i++) {
            const t = i / PARTICLES_PER_EDGE;

            // Interpolate 4D
            const x = v1[0] + (v2[0] - v1[0]) * t;
            const y = v1[1] + (v2[1] - v1[1]) * t;
            const z = v1[2] + (v2[2] - v1[2]) * t;
            const w = v1[3] + (v2[3] - v1[3]) * t;

            coords4D[pIdx*4] = x;
            coords4D[pIdx*4+1] = y;
            coords4D[pIdx*4+2] = z;
            coords4D[pIdx*4+3] = w;

            // Initial 3D placement
            positions[pIdx*3] = x * 10;
            positions[pIdx*3+1] = y * 10;
            positions[pIdx*3+2] = z * 10;

            colors[pIdx*3] = 1;
            colors[pIdx*3+1] = 1;
            colors[pIdx*3+2] = 1;

            pIdx++;
        }
    });

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    const getTexture = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 32;
        canvas.height = 32;
        const ctx = canvas.getContext('2d');
        if(ctx) {
            // Solid, bright square for retro vector look
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(4, 4, 24, 24);
        }
        return new THREE.CanvasTexture(canvas);
    };

    const material = new THREE.PointsMaterial({
        size: 0.25,
        map: getTexture(),
        transparent: true,
        opacity: 0.8,
        vertexColors: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
    });

    const particles = new THREE.Points(geometry, material);
    scene.add(particles);

    // --- MOUSE ---
    const mouse = new THREE.Vector2();
    const mouseParams = { active: false, x: 0, y: 0 };

    const handleMouseMove = (event: MouseEvent) => {
        const rect = mountRef.current?.getBoundingClientRect();
        if (!rect) return;
        mouse.x = ((event.clientX - rect.left) / width) * 2 - 1;
        mouse.y = -((event.clientY - rect.top) / height) * 2 + 1;
        mouseParams.active = true;
        mouseParams.x = mouse.x;
        mouseParams.y = mouse.y;
    };

    // --- ROTATION ---
    const rotate4D = (vec: number[], theta: number, plane: string) => {
        const [x, y, z, w] = vec;
        const s = Math.sin(theta);
        const c = Math.cos(theta);
        if(plane === 'xw') return [x*c - w*s, y, z, x*s + w*c];
        if(plane === 'yw') return [x, y*c - w*s, z, y*s + w*c];
        if(plane === 'zw') return [x, y, z*c - w*s, z*s + w*c];
        return [x, y, z, w];
    };

    // --- ANIMATION ---
    const clock = new THREE.Clock();
    let frameId: number;

    const animate = () => {
        frameId = requestAnimationFrame(animate);
        const time = clock.getElapsedTime();
        controls.update();

        // Stable Rotation
        let rx = time * 0.4;
        let ry = time * 0.25;

        // Mouse Twist Intensity
        let shatter = 0;
        if (mouseParams.active) {
            rx += mouseParams.x * 2.0;
            ry += mouseParams.y * 2.0;
            shatter = Math.sqrt(mouseParams.x*mouseParams.x + mouseParams.y*mouseParams.y);
        }

        const positions = geometry.attributes.position.array as Float32Array;
        const colors = geometry.attributes.color.array as Float32Array;
        const c4 = coords4D;

        // Camera distance in 4D
        const d = 3.5; 

        for (let i = 0; i < PARTICLE_COUNT; i++) {
            let x = c4[i*4];
            let y = c4[i*4+1];
            let z = c4[i*4+2];
            let w = c4[i*4+3];

            // 1. Rotation
            let v = [x, y, z, w];
            v = rotate4D(v, rx, 'xw');
            v = rotate4D(v, ry, 'zw');

            // Shatter Effect: Add noise based on mouse intensity
            if (shatter > 0.1) {
                const noise = Math.sin(i * 0.1 + time * 10) * shatter * 0.2;
                v[0] += noise;
                v[1] += noise;
                v[2] += noise;
            }

            [x, y, z, w] = v;

            // 2. Projection
            // Robust Stereographic: Scale = 1 / (d - w)
            // Clamp divisor to avoid singularity
            const dist = Math.max(0.5, d - w);
            const factor = 1 / dist;
            const scale = 12;

            positions[i*3] = x * factor * scale;
            positions[i*3+1] = y * factor * scale;
            positions[i*3+2] = z * factor * scale;

            // 3. Coloring - FORCE VIBRANCY
            // w goes roughly -2 to 2. Normalize to 0-1
            const depth = (w + 2) / 4; 

            // Mix colors based on 4D depth
            const c = c1.clone().lerp(c2, Math.max(0, Math.min(1, depth)));

            // Add white highlight if 'shattered' or close to camera (high w)
            if (w > 1.0 || shatter > 0.5) {
                c.lerp(c3, 0.5);
            }

            // DO NOT fade to black. Min brightness 0.6
            const brightness = 0.6 + 0.4 * (1/dist); 

            colors[i*3] = c.r * brightness;
            colors[i*3+1] = c.g * brightness;
            colors[i*3+2] = c.b * brightness;
        }

        geometry.attributes.position.needsUpdate = true;
        geometry.attributes.color.needsUpdate = true;

        renderer.render(scene, camera);
    };

    window.addEventListener('mousemove', handleMouseMove);
    animate();

    return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        cancelAnimationFrame(frameId);
        if (mountRef.current && renderer.domElement) {
             mountRef.current.removeChild(renderer.domElement);
        }
        controls.dispose();
        geometry.dispose();
        material.dispose();
        renderer.dispose();
    };
  }, [width, height]);

  return <div ref={mountRef} />;
};

