import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

interface SceneProps {
  width: number;
  height: number;
}

const SceneSupernova: React.FC<SceneProps> = ({ width, height }) => {
  const mountRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!mountRef.current) return;

    // --- SETUP ---
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x050005, 0.01);

    const camera = new THREE.PerspectiveCamera(75, width / height, 0.1, 1000);
    camera.position.set(0, 20, 60);

    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 0.2;

    // --- PARTICLES ---
    const PARTICLE_COUNT = 20000;
    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(PARTICLE_COUNT * 3);
    const velocities = new Float32Array(PARTICLE_COUNT * 3);
    const colors = new Float32Array(PARTICLE_COUNT * 3);
    const basePos = new Float32Array(PARTICLE_COUNT * 3); // To remember "stable" star shape

    // Initialize as a Star
    const cCore = new THREE.Color(0xffaa00);
    const cOuter = new THREE.Color(0xff0000);

    for (let i = 0; i < PARTICLE_COUNT; i++) {
        // Uniform sphere
        const theta = Math.random() * Math.PI * 2;
        const phi = Math.acos(2 * Math.random() - 1);
        const r = 10 + Math.random() * 2; // Surface of star

        const x = r * Math.sin(phi) * Math.cos(theta);
        const y = r * Math.sin(phi) * Math.sin(theta);
        const z = r * Math.cos(phi);

        positions[i*3] = x;
        positions[i*3+1] = y;
        positions[i*3+2] = z;

        basePos[i*3] = x;
        basePos[i*3+1] = y;
        basePos[i*3+2] = z;

        velocities[i*3] = (Math.random()-0.5) * 0.1;
        velocities[i*3+1] = (Math.random()-0.5) * 0.1;
        velocities[i*3+2] = (Math.random()-0.5) * 0.1;

        colors[i*3] = cCore.r;
        colors[i*3+1] = cCore.g;
        colors[i*3+2] = cCore.b;
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    const getTexture = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 32;
        canvas.height = 32;
        const ctx = canvas.getContext('2d');
        if(ctx) {
            const grad = ctx.createRadialGradient(16, 16, 0, 16, 16, 16);
            grad.addColorStop(0, 'rgba(255, 255, 255, 1)');
            grad.addColorStop(0.4, 'rgba(255, 200, 100, 0.5)');
            grad.addColorStop(1, 'rgba(0, 0, 0, 0)');
            ctx.fillStyle = grad;
            ctx.fillRect(0, 0, 32, 32);
        }
        return new THREE.CanvasTexture(canvas);
    };

    const material = new THREE.PointsMaterial({
        size: 0.8,
        map: getTexture(),
        transparent: true,
        opacity: 0.9,
        vertexColors: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
    });

    const particles = new THREE.Points(geometry, material);
    scene.add(particles);

    // --- STATE MACHINE ---
    enum Phase { STABLE, IMPLOSION, EXPLOSION, REMNANT }
    let phase = Phase.STABLE;
    let timer = 0;

    // --- MOUSE ---
    const mouseParams = { active: false };
    const handleMouseDown = () => {
        // Trigger cycle
        if (phase === Phase.STABLE || phase === Phase.REMNANT) {
            phase = Phase.IMPLOSION;
            timer = 0;
        }
    };

    // --- ANIMATION ---
    let frameId: number;
    const animate = () => {
        frameId = requestAnimationFrame(animate);
        timer += 0.016; // Approx dt
        controls.update();

        const p = geometry.attributes.position.array as Float32Array;
        const c = geometry.attributes.color.array as Float32Array;
        const v = velocities;

        for (let i = 0; i < PARTICLE_COUNT; i++) {
            const ix = i*3;
            let px = p[ix];
            let py = p[ix+1];
            let pz = p[ix+2];

            let vx = v[ix];
            let vy = v[ix+1];
            let vz = v[ix+2];

            const d = Math.sqrt(px*px + py*py + pz*pz);

            if (phase === Phase.STABLE) {
                // Turbulent surface
                const bx = basePos[ix];
                const by = basePos[ix+1];
                const bz = basePos[ix+2];

                // Spring to surface
                vx += (bx - px) * 0.05;
                vy += (by - py) * 0.05;
                vz += (bz - pz) * 0.05;

                // Random jitter (heat)
                vx += (Math.random()-0.5) * 0.2;
                vy += (Math.random()-0.5) * 0.2;
                vz += (Math.random()-0.5) * 0.2;

                // Color pulse
                if (Math.random() > 0.95) {
                    c[ix] = 1; c[ix+1] = 0.9; c[ix+2] = 0.5;
                } else {
                    c[ix] *= 0.95; // decay to red/orange
                    if(c[ix] < 0.8) { c[ix] = cCore.r; c[ix+1] = cCore.g; c[ix+2] = cCore.b; }
                }

            } else if (phase === Phase.IMPLOSION) {
                // Suck into center
                // Strong gravity
                const force = 0.5;
                vx -= (px/d) * force;
                vy -= (py/d) * force;
                vz -= (pz/d) * force;

                // Color turns blue/white (hotter)
                c[ix] = 0.5; c[ix+1] = 0.8; c[ix+2] = 1.0;

                if (timer > 1.5) {
                    phase = Phase.EXPLOSION;
                    timer = 0;
                }

            } else if (phase === Phase.EXPLOSION) {
                // Big Boom - Only apply once at start of phase? 
                // No, apply massive force if close to center
                if (d < 50 && timer < 0.1) {
                    const blast = 5.0 + Math.random() * 5.0;
                    vx = (px/d) * blast;
                    vy = (py/d) * blast;
                    vz = (pz/d) * blast;
                }

                // Drag
                vx *= 0.98;
                vy *= 0.98;
                vz *= 0.98;

                // Color fire
                c[ix] = 1.0; c[ix+1] = Math.random(); c[ix+2] = 0.0;

                if (timer > 2.0) phase = Phase.REMNANT;

            } else if (phase === Phase.REMNANT) {
                // Expanding nebula, slow drift
                vx *= 0.95; 
                vy *= 0.95;
                vz *= 0.95;

                // Gentle expansion
                vx += (px/d) * 0.005;
                vy += (py/d) * 0.005;
                vz += (pz/d) * 0.005;

                // Color purple/pink/nebula
                const t = Math.min(1, timer * 0.5);
                c[ix] += (0.5 - c[ix]) * 0.02; // Purple-ish target
                c[ix+1] += (0.0 - c[ix+1]) * 0.02;
                c[ix+2] += (0.8 - c[ix+2]) * 0.02;
            }

            // Update
            px += vx; py += vy; pz += vz;
            p[ix] = px; p[ix+1] = py; p[ix+2] = pz;
            v[ix] = vx; v[ix+1] = vy; v[ix+2] = vz;
        }

        geometry.attributes.position.needsUpdate = true;
        geometry.attributes.color.needsUpdate = true;

        renderer.render(scene, camera);
    };

    window.addEventListener('mousedown', handleMouseDown);
    animate();

    return () => {
        window.removeEventListener('mousedown', handleMouseDown);
        cancelAnimationFrame(frameId);
        if (mountRef.current && renderer.domElement) {
             mountRef.current.removeChild(renderer.domElement);
        }
        controls.dispose();
        geometry.dispose();
        material.dispose();
        renderer.dispose();
    };
  }, [width, height]);

  return <div ref={mountRef} />;
};

