import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

interface SceneProps {
  width: number;
  height: number;
}

const ScenePolyterra: React.FC<SceneProps> = ({ width, height }) => {
  const mountRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!mountRef.current) return;

    // --- SETUP ---
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x050510, 0.015);

    const camera = new THREE.PerspectiveCamera(60, width / height, 0.1, 1000);
    camera.position.set(0, 30, 40);
    camera.lookAt(0, 0, 0);

    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 0.5;

    // --- TERRAIN ---
    const WIDTH = 80;
    const DEPTH = 80;
    const SEGMENTS = 60;

    const geometry = new THREE.PlaneGeometry(WIDTH, DEPTH, SEGMENTS, SEGMENTS);
    geometry.rotateX(-Math.PI / 2);

    const count = geometry.attributes.position.count;
    const colors = new Float32Array(count * 3);
    const glitchOffset = new Float32Array(count); // Per-vertex random offset

    for(let i=0; i<count; i++) {
        glitchOffset[i] = Math.random() * 100;
    }

    const getNoise = (x: number, z: number, t: number) => {
        // More complex, jagged noise
        return Math.sin(x * 0.1 + t) * Math.cos(z * 0.1 + t * 0.5) * 4
             + Math.sin(x * 0.3 + z * 0.3 + t * 2) * 1.5
             + Math.sin(x * 1.0 + t) * 0.5;
    };

    // Initialize colors
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    const material = new THREE.MeshBasicMaterial({ 
        vertexColors: true, 
        wireframe: true,
        transparent: true,
        opacity: 0.8
    });

    const terrain = new THREE.Mesh(geometry, material);
    scene.add(terrain);

    // Stars
    const pGeo = new THREE.BufferGeometry();
    const pCount = 500;
    const pPos = new Float32Array(pCount * 3);
    for(let i=0; i<pCount; i++) {
        pPos[i*3] = (Math.random() - 0.5) * WIDTH * 1.5;
        pPos[i*3+1] = 10 + Math.random() * 20;
        pPos[i*3+2] = (Math.random() - 0.5) * DEPTH * 1.5;
    }
    pGeo.setAttribute('position', new THREE.BufferAttribute(pPos, 3));
    const pMat = new THREE.PointsMaterial({ color: 0xffffff, size: 0.2 });
    const stars = new THREE.Points(pGeo, pMat);
    scene.add(stars);


    // --- MOUSE ---
    const mouse = new THREE.Vector2();
    const raycaster = new THREE.Raycaster();
    const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
    const mouseParams = { active: false };

    const handleMouseMove = (event: MouseEvent) => {
        const rect = mountRef.current?.getBoundingClientRect();
        if (!rect) return;
        mouse.x = ((event.clientX - rect.left) / width) * 2 - 1;
        mouse.y = -((event.clientY - rect.top) / height) * 2 + 1;
        mouseParams.active = true;
    };

    // --- ANIMATION ---
    const clock = new THREE.Clock();
    let frameId: number;

    const animate = () => {
        frameId = requestAnimationFrame(animate);
        const time = clock.getElapsedTime();
        controls.update();

        raycaster.setFromCamera(mouse, camera);
        const intersect = new THREE.Vector3();
        raycaster.ray.intersectPlane(plane, intersect);

        const posAttr = geometry.attributes.position;
        const colAttr = geometry.attributes.color;

        // Glitch Timer
        const isGlitchFrame = Math.random() > 0.95; // 5% chance of frame glitch
        const sectorGlitch = Math.floor(time * 2) % 4; // Changing active sector

        for (let i = 0; i < count; i++) {
            const x = posAttr.getX(i);
            const z = posAttr.getZ(i);

            // Base Rolling Terrain
            let y = getNoise(x, z, time * 0.4);

            // Unpredictable Tectonics
            // Randomly shift height based on sector
            let sx = x > 0 ? 1 : 0;
            let sz = z > 0 ? 2 : 0;
            let sector = sx + sz; // 0, 1, 2, 3 quadrants

            if (sector === sectorGlitch) {
                // This sector is "unstable"
                y += Math.sin(time * 10 + glitchOffset[i]) * 0.5;
            }

            // Glitch Effect
            if (isGlitchFrame && Math.random() > 0.8) {
                 y += (Math.random() - 0.5) * 5; // Sudden spike
            }

            // Mouse Interaction: Jagged Terraforming
            if (mouseParams.active) {
                const dx = x - intersect.x;
                const dz = z - intersect.z;
                const d = Math.sqrt(dx*dx + dz*dz);
                if (d < 12) {
                    const factor = (12 - d) / 12;
                    // Create digital noise spikes near mouse
                    y += Math.sin(dx * 10 + dz * 10 + time * 20) * factor * 5;
                }
            }

            posAttr.setY(i, y);

            // Coloring
            let r = 0, g = 0.5, b = 0.8;

            // Highlight unstable sector
            if (sector === sectorGlitch) {
                r = 0.5; g = 0.8; b = 0.2; // Yellowish glitch
            }

            // Height-based gradient
            const h = y + 2;
            g += h * 0.1;
            b += h * 0.05;

            // Interaction highlight
            if (mouseParams.active) {
                 const dx = x - intersect.x;
                 const dz = z - intersect.z;
                 if (dx*dx + dz*dz < 144) {
                     r = 1.0; g = 1.0; b = 1.0; // White hot under mouse
                 }
            }

            colAttr.setXYZ(i, r, g, b);
        }

        posAttr.needsUpdate = true;
        colAttr.needsUpdate = true;

        stars.rotation.y = time * 0.05;

        renderer.render(scene, camera);
    };

    window.addEventListener('mousemove', handleMouseMove);
    animate();

    return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        cancelAnimationFrame(frameId);
        if (mountRef.current && renderer.domElement) {
             mountRef.current.removeChild(renderer.domElement);
        }
        controls.dispose();
        geometry.dispose();
        material.dispose();
        renderer.dispose();
    };
  }, [width, height]);

  return <div ref={mountRef} />;
};

