        const dz2 = (n2(x, y, z + eps) - n2(x, y, z - eps)) / (2 * eps);
        const dx3 = (n3(x + eps, y, z) - n3(x - eps, y, z)) / (2 * eps);
        const dy3 = (n3(x, y + eps, z) - n3(x, y - eps, z)) / (2 * eps);

        return { x: dy3 - dz2, y: dz1 - dx3, z: dx2 - dy1 };
    };

    // --- ANIMATION ---
    const clock = new THREE.Clock();
    let frameId: number;

    const animate = () => {
        frameId = requestAnimationFrame(animate);
        const time = clock.getElapsedTime();
        controls.update();

        raycaster.setFromCamera(mouse, camera);
        const target = new THREE.Vector3();
        raycaster.ray.intersectPlane(plane, target);

        const positions = geometry.attributes.position.array as Float32Array;
        const colors = geometry.attributes.color.array as Float32Array;

        for (let i = 0; i < PARTICLE_COUNT; i++) {
            const ix = i * 3;
            let px = positions[ix];
            let py = positions[ix+1];
            let pz = positions[ix+2];

            // 1. Curl Noise Flow
            const v = computeCurl(px, py, pz, time * 0.5);

            // 2. Strong Mouse Disruption
            if (mouseParams.active) {
                const dx = px - target.x;
                const dy = py - target.y;
                const dz = pz - target.z;
                const dSq = dx*dx + dy*dy + dz*dz;

                // Huge range of influence
                if (dSq < 900) { 
                    const f = (900 - dSq) / 900;
                    // Vortex / Repulsion mix
                    v.x += dx * f * 20.0; // STRONG Push
                    v.y += dy * f * 20.0;
                    v.z += dz * f * 20.0;
                }
            }

            px += v.x * 0.4;
            py += v.y * 0.4;
            pz += v.z * 0.4;

            // Wrap
            const BOUND = 40;
            if (px > BOUND) px -= BOUND * 2;
            if (px < -BOUND) px += BOUND * 2;
            if (py > BOUND) py -= BOUND * 2;
            if (py < -BOUND) py += BOUND * 2;
            if (pz > BOUND) pz -= BOUND * 2;
            if (pz < -BOUND) pz += BOUND * 2;

            positions[ix] = px;
            positions[ix+1] = py;
            positions[ix+2] = pz;

            // 3. Visuals based on velocity
            const speed = Math.sqrt(v.x*v.x + v.y*v.y + v.z*v.z);

            // Velocity Color Mapping
            // High speed = white/bright cyan, Low speed = deep blue
            const t = Math.min(1, speed * 0.5);
            const c = c2.clone().lerp(c1, t);
            if (speed > 2.0) c.setHex(0xffffff);

            colors[ix] = c.r;
            colors[ix+1] = c.g;
            colors[ix+2] = c.b;

            // Faux-stretching by jittering position slightly based on velocity for motion blur feel?
            // Real stretching requires shaders. 
            // We can approximate by coloring the tail lighter or lower opacity? 
            // Let's stick to color intensity.
        }

        geometry.attributes.position.needsUpdate = true;
        geometry.attributes.color.needsUpdate = true;

        renderer.render(scene, camera);
    };

    window.addEventListener('mousemove', handleMouseMove);
    animate();

    return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        cancelAnimationFrame(frameId);
        if (mountRef.current && renderer.domElement) {
             mountRef.current.removeChild(renderer.domElement);
        }
        controls.dispose();
        geometry.dispose();
        material.dispose();
        renderer.dispose();
    };
  }, [width, height]);

  return <div ref={mountRef} />;
};

