import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { MeshSurfaceSampler } from 'three/addons/math/MeshSurfaceSampler.js';

interface SceneProps {
  width: number;
  height: number;
}

const SceneCrystal: React.FC<SceneProps> = ({ width, height }) => {
  const mountRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!mountRef.current) return;

    // --- SETUP ---
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x050510, 0.02); // Dark blue/grey

    const camera = new THREE.PerspectiveCamera(75, width / height, 0.1, 1000);
    camera.position.set(0, 0, 40);

    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 0.3;

    // --- CRYSTAL GEOMETRY (Torus Knot) ---
    // We create a hidden mesh to sample points from
    const knotGeo = new THREE.TorusKnotGeometry(10, 3, 100, 16);
    const knotMat = new THREE.MeshBasicMaterial({ wireframe: true, color: 0x222222, transparent: true, opacity: 0.1 });
    const knotMesh = new THREE.Mesh(knotGeo, knotMat);
    scene.add(knotMesh); // Show faint wireframe for structure

    const sampler = new MeshSurfaceSampler(knotMesh).build();

    const PARTICLE_COUNT = 8000;
    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(PARTICLE_COUNT * 3);
    const targets = new Float32Array(PARTICLE_COUNT * 3); // The "crystal" lattice positions
    const colors = new Float32Array(PARTICLE_COUNT * 3);

    const tempPos = new THREE.Vector3();
    const c1 = new THREE.Color(0x00ff88); // Emerald
    const c2 = new THREE.Color(0x0088ff); // Sapphire

    for (let i = 0; i < PARTICLE_COUNT; i++) {
        sampler.sample(tempPos, new THREE.Vector3()); // Sample random point on surface

        positions[i*3] = tempPos.x;
        positions[i*3+1] = tempPos.y;
        positions[i*3+2] = tempPos.z;

        targets[i*3] = tempPos.x;
        targets[i*3+1] = tempPos.y;
        targets[i*3+2] = tempPos.z;

        // Gradient color based on position
        const t = (tempPos.y + 10) / 20;
        const c = c1.clone().lerp(c2, t);

        colors[i*3] = c.r;
        colors[i*3+1] = c.g;
        colors[i*3+2] = c.b;
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    // Crystal shard texture
    const getTexture = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 32;
        canvas.height = 32;
        const ctx = canvas.getContext('2d');
        if(ctx) {
            ctx.fillStyle = '#ffffff';
            // Draw a diamond shape
            ctx.beginPath();
            ctx.moveTo(16, 0);
            ctx.lineTo(32, 16);
            ctx.lineTo(16, 32);
            ctx.lineTo(0, 16);
            ctx.fill();
        }
        return new THREE.CanvasTexture(canvas);
    };

    const material = new THREE.PointsMaterial({
        size: 0.5,
        map: getTexture(),
        transparent: true,
        opacity: 0.8,
        vertexColors: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
    });

    const particles = new THREE.Points(geometry, material);
    scene.add(particles);

    // --- MOUSE ---
    const mouse = new THREE.Vector2();
    const raycaster = new THREE.Raycaster();
    const mouseParams = { active: false };

    const handleMouseMove = (event: MouseEvent) => {
        const rect = mountRef.current?.getBoundingClientRect();
        if (!rect) return;
        mouse.x = ((event.clientX - rect.left) / width) * 2 - 1;
        mouse.y = -((event.clientY - rect.top) / height) * 2 + 1;
        mouseParams.active = true;
    };

    // --- ANIMATION ---
    const clock = new THREE.Clock();
    let frameId: number;

    const animate = () => {
        frameId = requestAnimationFrame(animate);
        const time = clock.getElapsedTime();
        controls.update();

        // Rotate the target mesh logically (positions need to rotate too if we want them to stick)
        // Actually, simplest way: The particles ARE the mesh. We just animate them.

        // Let's rotate the whole group
        particles.rotation.y = time * 0.1;
        particles.rotation.x = time * 0.05;
        knotMesh.rotation.y = time * 0.1;
        knotMesh.rotation.x = time * 0.05;

        // Interaction Logic: Shattering
        // We need world coordinates for raycasting
        raycaster.setFromCamera(mouse, camera);

        // To interact with the rotating particles, we project the ray into the object's local space?
        // Or simpler: project mouse to a plane and check distance.
        // Let's use a plane at z=0 (camera relative)
        const planeZ = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
        const target = new THREE.Vector3();
        raycaster.ray.intersectPlane(planeZ, target);

        const positions = geometry.attributes.position.array as Float32Array;

        // Since the particles object rotates, we need to account for that when checking distance
        // Inverse rotation on the mouse target? 
        // Or just map distance in screen space? Screen space is expensive to project every point.
        // Let's approximate.

        for (let i = 0; i < PARTICLE_COUNT; i++) {
            const ix = i * 3;
            let px = positions[ix];
            let py = positions[ix+1];
            let pz = positions[ix+2];

            const tx = targets[ix];
            const ty = targets[ix+1];
            const tz = targets[ix+2];

            // Transform local P to World for distance check
            const vWorld = new THREE.Vector3(px, py, pz).applyMatrix4(particles.matrixWorld);

            // Shatter Force
            let shatter = false;
            if (mouseParams.active) {
                // Check distance to ray
                // raycaster.ray.distanceToPoint(vWorld) is accurate but expensive loop?
                // distanceToPoint is okay for 8000 particles in modern JS engines.
                const dist = raycaster.ray.distanceToPoint(vWorld);

                if (dist < 5) {
                    shatter = true;
                    // Push away from ray
                    // Calculate vector from ray closest point to particle
                    // simplified: push away from camera ray origin or target?
                    // Let's just add noise + outward vector

                    const noise = Math.random() * 2;
                    positions[ix] += (Math.random() - 0.5) * noise;
                    positions[ix+1] += (Math.random() - 0.5) * noise;
                    positions[ix+2] += (Math.random() - 0.5) * noise;
                }
            }

            // Return to Shape (Crystal Memory)
            if (!shatter) {
                positions[ix] += (tx - px) * 0.05;
                positions[ix+1] += (ty - py) * 0.05;
                positions[ix+2] += (tz - pz) * 0.05;
            }
        }

        geometry.attributes.position.needsUpdate = true;
        renderer.render(scene, camera);
    };

    window.addEventListener('mousemove', handleMouseMove);
    animate();

    return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        cancelAnimationFrame(frameId);
        if (mountRef.current && renderer.domElement) {
             mountRef.current.removeChild(renderer.domElement);
        }
        controls.dispose();
        geometry.dispose();
        material.dispose();
        renderer.dispose();
    };
  }, [width, height]);

  return <div ref={mountRef} />;
};

