import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

interface SceneProps {
  width: number;
  height: number;
}

const SceneLattice: React.FC<SceneProps> = ({ width, height }) => {
  const mountRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!mountRef.current) return;

    // --- SETUP ---
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x001100, 0.015); // Dark Green Matrix Fog

    const camera = new THREE.PerspectiveCamera(75, width / height, 0.1, 1000);
    camera.position.set(30, 30, 30);
    camera.lookAt(0, 0, 0);

    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 0.5;

    // --- PARTICLES ---
    // Create a 3D Grid
    const DIM = 20; // 20x20x20 grid
    const SPACING = 2.5;
    const PARTICLE_COUNT = DIM * DIM * DIM;

    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(PARTICLE_COUNT * 3);
    const basePositions = new Float32Array(PARTICLE_COUNT * 3); // Rest positions
    const colors = new Float32Array(PARTICLE_COUNT * 3);

    const color1 = new THREE.Color(0x00ff00); // Neon Green
    const color2 = new THREE.Color(0x003300); // Dark Green
    const color3 = new THREE.Color(0xffffff); // White highlight

    let idx = 0;
    const offset = (DIM * SPACING) / 2;

    for (let x = 0; x < DIM; x++) {
        for (let y = 0; y < DIM; y++) {
            for (let z = 0; z < DIM; z++) {
                const px = x * SPACING - offset;
                const py = y * SPACING - offset;
                const pz = z * SPACING - offset;

                positions[idx * 3] = px;
                positions[idx * 3 + 1] = py;
                positions[idx * 3 + 2] = pz;

                basePositions[idx * 3] = px;
                basePositions[idx * 3 + 1] = py;
                basePositions[idx * 3 + 2] = pz;

                // Checkerboard coloring essentially
                const c = (x+y+z)%2 === 0 ? color1 : color2;
                colors[idx * 3] = c.r;
                colors[idx * 3 + 1] = c.g;
                colors[idx * 3 + 2] = c.b;

                idx++;
            }
        }
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    // Sharp square texture for digital look
    const getTexture = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 32;
        canvas.height = 32;
        const ctx = canvas.getContext('2d');
        if(ctx) {
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(8, 8, 16, 16); // small square
        }
        return new THREE.CanvasTexture(canvas);
    };

    const material = new THREE.PointsMaterial({
        size: 0.3,
        map: getTexture(),
        transparent: true,
        opacity: 0.8,
        vertexColors: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
    });

    const particles = new THREE.Points(geometry, material);
    scene.add(particles);

    // --- CORE (Octahedron) ---
    const coreGeo = new THREE.OctahedronGeometry(2, 0);
    const coreMat = new THREE.MeshBasicMaterial({ 
        color: 0x00ff00, 
        wireframe: true,
        transparent: true,
        opacity: 0.5 
    });
    const coreMesh = new THREE.Mesh(coreGeo, coreMat);
    scene.add(coreMesh);

    const innerCoreGeo = new THREE.OctahedronGeometry(1, 0);
    const innerCoreMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
    const innerCoreMesh = new THREE.Mesh(innerCoreGeo, innerCoreMat);
    scene.add(innerCoreMesh);

    // --- MOUSE ---
    const mouse = new THREE.Vector2();
    const raycaster = new THREE.Raycaster();
    const mouseParams = { active: false };

    const handleMouseMove = (event: MouseEvent) => {
        const rect = mountRef.current?.getBoundingClientRect();
        if (!rect) return;
        mouse.x = ((event.clientX - rect.left) / width) * 2 - 1;
        mouse.y = -((event.clientY - rect.top) / height) * 2 + 1;
        mouseParams.active = true;
    };

    // --- ANIMATION ---
    const clock = new THREE.Clock();
    let frameId: number;

    const animate = () => {
        frameId = requestAnimationFrame(animate);
        const time = clock.getElapsedTime();

        controls.update();

        // Core Animation
        coreMesh.rotation.x = time;
        coreMesh.rotation.y = time * 0.5;
        innerCoreMesh.rotation.x = -time;

        // Wave Physics
        const positions = geometry.attributes.position.array as Float32Array;

        // Mouse Raycast for point of disturbance
        raycaster.setFromCamera(mouse, camera);
        const ray = raycaster.ray;

        // Find nearest point on a virtual plane facing camera for simplified interaction logic
        // or just use origin for waves + mouse offset
        let targetX = 0, targetY = 0, targetZ = 0;

        if (mouseParams.active) {
            // Project mouse ray to z=0 or similar depth
            const target = new THREE.Vector3();
            ray.at(30, target); // Project out
            targetX = target.x;
            targetY = target.y;
            targetZ = target.z;
        }

        for (let i = 0; i < PARTICLE_COUNT; i++) {
            const ix = i * 3;

            const bx = basePositions[ix];
            const by = basePositions[ix + 1];
            const bz = basePositions[ix + 2];

            // 1. Global Wave
            const distFromCenter = Math.sqrt(bx*bx + by*by + bz*bz);
            const wave = Math.sin(distFromCenter * 0.2 - time * 3) * 0.5;

            // 2. Mouse Disturbance (Digital Glitch)
            let dx = 0, dy = 0, dz = 0;
            if (mouseParams.active) {
                // simple distance to mouse ray projection
                const mdx = bx - targetX;
                const mdy = by - targetY;
                const mdz = bz - targetZ;
                const d = Math.sqrt(mdx*mdx + mdy*mdy + mdz*mdz);

                if (d < 15) {
                    const force = (15 - d) / 15;
                    // Random glitch jitter
                    dx = (Math.random() - 0.5) * force * 2;
                    dy = (Math.random() - 0.5) * force * 2;
                    dz = (Math.random() - 0.5) * force * 2;
                }
            }

            positions[ix] = bx + dx;
            positions[ix + 1] = by + wave + dy; // Apply wave to Y axis mostly
            positions[ix + 2] = bz + dz;
        }

        geometry.attributes.position.needsUpdate = true;
        renderer.render(scene, camera);
    };

    window.addEventListener('mousemove', handleMouseMove);
    animate();

    return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        cancelAnimationFrame(frameId);
        if (mountRef.current && renderer.domElement) {
             mountRef.current.removeChild(renderer.domElement);
        }
        controls.dispose();
        geometry.dispose();
        material.dispose();
        renderer.dispose();
    };
  }, [width, height]);

  return <div ref={mountRef} />;
};

