    let frameId: number;

    const animate = () => {
        frameId = requestAnimationFrame(animate);
        const time = clock.getElapsedTime();

        controls.update();

        // Breathing Calculation
        const breath = Math.sin(time * 1.5) * 0.1 + 1; // 0.9 to 1.1 scale

        // Mouse Interact
        raycaster.setFromCamera(mouse, camera);
        const intersect = new THREE.Vector3();
        raycaster.ray.intersectPlane(plane, intersect);

        const positions = geometry.attributes.position.array as Float32Array;
        const colors = geometry.attributes.color.array as Float32Array;

        for (let i = 0; i < PARTICLE_COUNT; i++) {
            const ix = i * 3;
            const ox = originals[ix];
            const oy = originals[ix+1];
            const oz = originals[ix+2];
            const ph = phases[i];

            // 1. Breathing expansion
            let x = ox * breath;
            let y = oy * breath;
            let z = oz * breath;

            // 2. Organic undulation (Perlin-ish sine waves)
            const noise = Math.sin(time * 2 + ox * 0.2) * Math.cos(time + oy * 0.2);
            x += noise * 0.5;
            y += noise * 0.5;
            z += noise * 0.5;

            // 3. Mouse "Excitement" / Reaction
