            if (mouseParams.active) {
                // Check distance to mouse ray in 3D (approximate)
                // Project particle to camera plane
                const v = new THREE.Vector3(x, y, z).project(camera);
                const dx = v.x - mouse.x;
                const dy = v.y - mouse.y;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist < 0.3) {
                    excitement = (0.3 - dist) / 0.3;
                    // Jitter
                    x += (Math.random() - 0.5) * 2;
                    y += (Math.random() - 0.5) * 2;
                    z += (Math.random() - 0.5) * 2;
                }
            }

            positions[ix] = x;
            positions[ix+1] = y;
            positions[ix+2] = z;

            // Bioluminescence flash
            if (excitement > 0) {
                colors[ix] = 1;
                colors[ix+1] = 1;
                colors[ix+2] = 1;
            } else {
                // Pulse logic
                const pulse = Math.sin(time * 3 + ph) > 0.9 ? 1.5 : 1.0;
                // Revert slow to original
                // (Omitted for CPU performance, simpler visual logic: just keep static gradient or slight pulse)
                // Let's just reset slightly to original + pulse
                // Not perfectly reverting to exact original color for speed, just keeping hue logic
                // Actually, let's just leave color static unless excited.
                 if (colors[ix] > 0.8 && colors[ix+1] > 0.8) {
                    // decay white back to teal
                    colors[ix] *= 0.95;
                    colors[ix+1] *= 0.95;
                    colors[ix+2] *= 0.99; 
                 }
            }
        }

        geometry.attributes.position.needsUpdate = true;
        geometry.attributes.color.needsUpdate = true;

        nucleus.rotation.y = time * 0.2;
        nucleus.rotation.z = time * 0.1;
        nucleus.scale.set(breath * 0.8, breath * 0.8, breath * 0.8);

        renderer.render(scene, camera);
    };

    window.addEventListener('mousemove', handleMouseMove);
    animate();

    return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        cancelAnimationFrame(frameId);
        if (mountRef.current && renderer.domElement) {
             mountRef.current.removeChild(renderer.domElement);
        }
        controls.dispose();
        geometry.dispose();
        material.dispose();
        renderer.dispose();
    };
  }, [width, height]);

  return <div ref={mountRef} />;
};

