    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 1.0;

    // --- PARTICLES ---
    const PARTICLE_COUNT = 15000;
    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(PARTICLE_COUNT * 3);
    const velocities = new Float32Array(PARTICLE_COUNT * 3); // Current velocity
    const colors = new Float32Array(PARTICLE_COUNT * 3);

    // Store orbit data
    const angles = new Float32Array(PARTICLE_COUNT);
    const radii = new Float32Array(PARTICLE_COUNT);
    const speeds = new Float32Array(PARTICLE_COUNT);

    const c1 = new THREE.Color(0xff3300); // Red
    const c2 = new THREE.Color(0xffcc00); // Yellow
    const c3 = new THREE.Color(0x00ffff); // Shockwave Cyan

    for (let i = 0; i < PARTICLE_COUNT; i++) {
        const r = 5 + Math.random() * Math.random() * 50; 
        const theta = Math.random() * Math.PI * 2;

        radii[i] = r;
        angles[i] = theta;
        speeds[i] = Math.sqrt(800 / r) * 0.01; 

        const x = r * Math.cos(theta);
        const z = r * Math.sin(theta);
        const y = (Math.random() - 0.5) * (r * 0.05); 

        positions[i*3] = x;
        positions[i*3+1] = y;
        positions[i*3+2] = z;

        const t = 1 - (r / 50);
        const c = c1.clone().lerp(c2, t);
        colors[i*3] = c.r;
        colors[i*3+1] = c.g;
        colors[i*3+2] = c.b;
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    const getTexture = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 32;
        canvas.height = 32;
        const ctx = canvas.getContext('2d');
        if(ctx) {
            const grad = ctx.createRadialGradient(16, 16, 0, 16, 16, 16);
            grad.addColorStop(0, 'rgba(255, 255, 255, 1)');
            grad.addColorStop(0.2, 'rgba(255, 100, 50, 0.8)');
            grad.addColorStop(1, 'rgba(0, 0, 0, 0)');
            ctx.fillStyle = grad;
            ctx.fillRect(0, 0, 32, 32);
        }
        return new THREE.CanvasTexture(canvas);
    };

    const material = new THREE.PointsMaterial({
        size: 0.5,
        map: getTexture(),
        transparent: true,
        opacity: 0.8,
        vertexColors: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
    });

    const particles = new THREE.Points(geometry, material);
    scene.add(particles);

    // Black Hole
    const sphereGeo = new THREE.SphereGeometry(4, 32, 32);
    const sphereMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
    const blackHole = new THREE.Mesh(sphereGeo, sphereMat);
    scene.add(blackHole);

    // Accretion Halo
    const haloGeo = new THREE.RingGeometry(4.1, 5.0, 64);
    const haloMat = new THREE.MeshBasicMaterial({ color: 0xffaa00, side: THREE.DoubleSide, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending });
    const halo = new THREE.Mesh(haloGeo, haloMat);
    scene.add(halo);

    // --- INTERACTION STATE ---
    const raycaster = new THREE.Raycaster();
    const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); // Intersection plane at y=0
    const mouse = new THREE.Vector2();

    const shockwaves: { x: number, y: number, z: number, radius: number, active: boolean }[] = [];

    const handleMouseDown = (event: MouseEvent) => {
        const rect = mountRef.current?.getBoundingClientRect();
        if (!rect) return;
        mouse.x = ((event.clientX - rect.left) / width) * 2 - 1;
        mouse.y = -((event.clientY - rect.top) / height) * 2 + 1;

        raycaster.setFromCamera(mouse, camera);
        const target = new THREE.Vector3();
        raycaster.ray.intersectPlane(plane, target);

        if (target) {
            // Spawn new shockwave at mouse location
            shockwaves.push({
                x: target.x,
                y: target.y,
                z: target.z,
                radius: 0,
                active: true
            });
        }
    };

    // --- ANIMATION ---
    const clock = new THREE.Clock();
    let frameId: number;

    const animate = () => {
        frameId = requestAnimationFrame(animate);
        controls.update();

        // Update Shockwaves
        for(let i = shockwaves.length - 1; i >= 0; i--) {
            const wave = shockwaves[i];
            if (wave.active) {
                wave.radius += 2.0; // Expand
                if (wave.radius > 100) {
                    wave.active = false;
                    shockwaves.splice(i, 1);
                }
            }
        }

        const positions = geometry.attributes.position.array as Float32Array;
        const colors = geometry.attributes.color.array as Float32Array;

        for (let i = 0; i < PARTICLE_COUNT; i++) {
            const ix = i * 3;
            let px = positions[ix];
            let py = positions[ix+1];
            let pz = positions[ix+2];

            let vx = velocities[ix];
            let vy = velocities[ix+1];
            let vz = velocities[ix+2];

            // 1. Shockwave Logic
            shockwaves.forEach(wave => {
                const dx = px - wave.x;
                const dy = py - wave.y;
                const dz = pz - wave.z;
                const d = Math.sqrt(dx*dx + dy*dy + dz*dz);

                // If particle is hit by wavefront
                if (Math.abs(d - wave.radius) < 5) {
                    const blastForce = 3.0; // Strong impulse
                    vx += (dx / d) * blastForce;
                    vy += (dy / d) * blastForce * 0.5; // less vertical blast
                    vz += (dz / d) * blastForce;

                    // Color Flash
                    colors[ix] = c3.r; 
                    colors[ix+1] = c3.g; 
                    colors[ix+2] = c3.b;
                }
            });

            // 2. Gravitational Recollection & Orbit
            const idealR = radii[i];
            const currentR = Math.sqrt(px*px + py*py + pz*pz);

            // Drag
            vx *= 0.96; 
            vy *= 0.96;
            vz *= 0.96;

            // Orbital Velocity
            const s = speeds[i];
            const tx = -pz;
            const tz = px;
            const tLen = Math.sqrt(tx*tx + tz*tz);

            if (tLen > 0.1) {
                vx += (tx / tLen) * s;
                vz += (tz / tLen) * s;
            }

            // Gravity (Center Attraction)
            const g = (idealR - currentR) * 0.05; 
            if (currentR > 0.1) {
                vx += (px / currentR) * g;
                vz += (pz / currentR) * g;
                vy -= py * 0.1; // Pull to plane strongly
            }

            // Update Position
            px += vx;
            py += vy;
            pz += vz;

            positions[ix] = px;
            positions[ix+1] = py;
            positions[ix+2] = pz;

            velocities[ix] = vx;
            velocities[ix+1] = vy;
            velocities[ix+2] = vz;

            // Color Restoration
            const tColor = 1 - (Math.min(50, currentR) / 50);
            const c = c1.clone().lerp(c2, tColor);
            colors[ix] += (c.r - colors[ix]) * 0.02;
            colors[ix+1] += (c.g - colors[ix+1]) * 0.02;
            colors[ix+2] += (c.b - colors[ix+2]) * 0.02;
        }

        geometry.attributes.position.needsUpdate = true;
        geometry.attributes.color.needsUpdate = true;

        // Visual for active shockwaves?
        // We could render a ring for each, but particles show it well enough.

        // Halo billboard
        halo.lookAt(camera.position);

        renderer.render(scene, camera);
    };

    window.addEventListener('mousedown', handleMouseDown);
    animate();

    return () => {
        window.removeEventListener('mousedown', handleMouseDown);
        cancelAnimationFrame(frameId);
        if (mountRef.current && renderer.domElement) {
             mountRef.current.removeChild(renderer.domElement);
        }
        controls.dispose();
        geometry.dispose();
        material.dispose();
        renderer.dispose();
    };
  }, [width, height]);

  return <div ref={mountRef} />;
};

