        const armOffset = (i % arms) * (Math.PI * 2 / arms);
        const spiralAngle = angle + radius * 0.1 + armOffset;

        // Spread particles vertically based on radius (thicker at center)
        const thickness = Math.max(2, 15 - radius * 0.2); 
        const y = (Math.random() - 0.5) * thickness;

        const x = Math.cos(spiralAngle) * radius;
        const z = Math.sin(spiralAngle) * radius;

        positions[i * 3] = x;
        positions[i * 3 + 1] = y;
        positions[i * 3 + 2] = z;

