        mouseParams.active = true;
    };

    // --- ANIMATION ---
    const clock = new THREE.Clock();
    let frameId: number;

    const animate = () => {
        frameId = requestAnimationFrame(animate);
        const time = clock.getElapsedTime();

        controls.update();

        // Mouse Interactivity
        raycaster.setFromCamera(mouse, camera);
        const target = new THREE.Vector3();
        raycaster.ray.intersectPlane(plane, target);

        const positions = geometry.attributes.position.array as Float32Array;
        const colors = geometry.attributes.color.array as Float32Array;

        for (let i = 0; i < PARTICLE_COUNT; i++) {
            const ix = i * 3;
            const r = initialData[i * 4];
            const startAngle = initialData[i * 4 + 1];
            const startH = initialData[i * 4 + 2];
            const rnd = initialData[i * 4 + 3];

            // Complex Orbital Mechanics
            // Closer to center = faster (Kepler)
            let speed = (100 / (r * r + 10)) * 0.2; 

            // Mouse Warp Effect: If mouse is active, distort speed and height
            let warpFactor = 0;
            if (mouseParams.active) {
                // Calculate distance from particle to mouse projection
                const dx = positions[ix] - target.x;
                const dz = positions[ix+2] - target.z;
                const d = Math.sqrt(dx*dx + dz*dz);

                if (d < 20) {
                    warpFactor = (20 - d) / 20;
                    speed += warpFactor * 0.5; // Speed up near mouse
                }
            }

            const currentAngle = startAngle + time * speed;

            // Turbulence / Vertical Wave
            // Create a wave that ripples through the galaxy arms
            const wave = Math.sin(r * 0.5 - time * 2) * Math.cos(currentAngle * 2);
            let y = startH + wave * (r * 0.05);

            // Add Warp Verticality
            y += warpFactor * Math.sin(time * 10 + r) * 5;

            let x = Math.cos(currentAngle) * r;
            let z = Math.sin(currentAngle) * r;

            positions[ix] = x;
            positions[ix + 1] = y;
            positions[ix + 2] = z;

            // Color Dynamics: Heat up when moving fast or warped
            if (warpFactor > 0.1) {
                colors[ix] = 1.0;
                colors[ix+1] = 1.0;
                colors[ix+2] = 1.0;
            } else {
                // Reset to roughly original gradient (cheap approximation)
