        const colors = geometry.attributes.color.array as Float32Array;

        // Global Flow Direction (Swirling)
        const globalFlow = new THREE.Vector3(
            Math.sin(time * 0.5) * 0.1,
            Math.cos(time * 0.3) * 0.1,
            Math.sin(time * 0.7) * 0.1
        );

        for (let i = 0; i < PARTICLE_COUNT; i++) {
            const ix = i * 3;
            let px = positions[ix];
            let py = positions[ix+1];
            let pz = positions[ix+2];

            let vx = velocities[ix];
            let vy = velocities[ix+1];
            let vz = velocities[ix+2];

            // 1. Cohesion (Attract to Center/Hive)
            const dCenter = Math.sqrt(px*px + py*py + pz*pz);
            const centerForce = 0.005;
            vx -= px * centerForce;
            vy -= py * centerForce;
            vz -= pz * centerForce;

            // 2. Alignment (Follow Global Flow + Noise)
            // Simulating local alignment via global field + perlin-ish noise
            const noise = Math.sin(px * 0.1 + time) * Math.cos(py * 0.1 + time);
            vx += (globalFlow.x + noise * 0.05) * 0.5;
            vy += (globalFlow.y + noise * 0.05) * 0.5;
            vz += (globalFlow.z + noise * 0.05) * 0.5;

            // 3. Separation / Predator Avoidance (Mouse)
            let panic = false;
            if (mouseParams.active) {
                const dx = px - target.x;
                const dy = py - target.y;
                const dz = pz - target.z;
                const dist = Math.sqrt(dx*dx + dy*dy + dz*dz);

                if (dist < 15) {
                    panic = true;
                    const force = (15 - dist) / 15;
                    // Flee hard
                    vx += dx * force * 0.8;
                    vy += dy * force * 0.8;
                    vz += dz * force * 0.8;
                }
            }

            // Speed Limit
            const speed = Math.sqrt(vx*vx + vy*vy + vz*vz);
            const maxSpeed = panic ? 1.5 : 0.8;
            if (speed > maxSpeed) {
                vx = (vx / speed) * maxSpeed;
                vy = (vy / speed) * maxSpeed;
                vz = (vz / speed) * maxSpeed;
            }

            // Update
            positions[ix] += vx;
            positions[ix+1] += vy;
            positions[ix+2] += vz;

            velocities[ix] = vx;
            velocities[ix+1] = vy;
            velocities[ix+2] = vz;

            // Color
            if (panic) {
                colors[ix] = c3.r; colors[ix+1] = c3.g; colors[ix+2] = c3.b;
            } else {
                // Gradient based on distance from hive
                const t = Math.min(1, dCenter / 30);
                const c = c1.clone().lerp(c2, t);
                colors[ix] = c.r; colors[ix+1] = c.g; colors[ix+2] = c.b;
            }
        }

        geometry.attributes.position.needsUpdate = true;
        geometry.attributes.color.needsUpdate = true;

        coreMesh.rotation.y -= 0.01;
        coreMesh.rotation.z += 0.005;

        renderer.render(scene, camera);
    };

    window.addEventListener('mousemove', handleMouseMove);
    animate();

    return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        cancelAnimationFrame(frameId);
        if (mountRef.current && renderer.domElement) {
             mountRef.current.removeChild(renderer.domElement);
        }
        controls.dispose();
        geometry.dispose();
        material.dispose();
        renderer.dispose();
    };
  }, [width, height]);

  return <div ref={mountRef} />;
};

export default SceneSwarm;

import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { MeshSurfaceSampler } from 'three/addons/math/MeshSurfaceSampler.js';

interface SceneProps {
  width: number;
  height: number;
}

const SceneQuantum: React.FC<SceneProps> = ({ width, height }) => {
  const mountRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!mountRef.current) return;

    // --- SCENE SETUP ---
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x020205, 0.02);

    const camera = new THREE.PerspectiveCamera(75, width / height, 0.1, 1000);
    camera.position.z = 30;
    camera.position.y = 5;

    const renderer = new THREE.WebGLRenderer({ 
      alpha: true, 
      antialias: true,
      powerPreference: "high-performance"
    });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    mountRef.current.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 0.5;

    // --- LIGHTING ---
    const ambientLight = new THREE.AmbientLight(0x404040, 2);
    scene.add(ambientLight);

    const centerLight = new THREE.PointLight(0x00ffff, 5, 50);
    scene.add(centerLight);

    const purpleLight = new THREE.PointLight(0xaa00ff, 3, 50);
    purpleLight.position.set(10, 10, 10);
    scene.add(purpleLight);

    // --- PARTICLES SETUP ---
    const PARTICLE_COUNT = 8000;
    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(PARTICLE_COUNT * 3);
    const targets = new Float32Array(PARTICLE_COUNT * 3);
    const velocities = new Float32Array(PARTICLE_COUNT * 3);
    const colors = new Float32Array(PARTICLE_COUNT * 3);
    const randomness = new Float32Array(PARTICLE_COUNT);

    const color1 = new THREE.Color(0x00ffff);
    const color2 = new THREE.Color(0xaa00ff);

    for (let i = 0; i < PARTICLE_COUNT; i++) {
        const r = 15 + Math.random() * 15;
        const theta = Math.random() * Math.PI * 2;
        const phi = Math.acos(2 * Math.random() - 1);

        const x = r * Math.sin(phi) * Math.cos(theta);
        const y = r * Math.sin(phi) * Math.sin(theta);
        const z = r * Math.cos(phi);

        positions[i * 3] = x;
        positions[i * 3 + 1] = y;
        positions[i * 3 + 2] = z;

        targets[i * 3] = x;
        targets[i * 3 + 1] = y;
        targets[i * 3 + 2] = z;

        const alpha = Math.random();
        const c = color1.clone().lerp(color2, alpha);
        colors[i * 3] = c.r;
        colors[i * 3 + 1] = c.g;
        colors[i * 3 + 2] = c.b;

        randomness[i] = Math.random();
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    const getTexture = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 32;
        canvas.height = 32;
        const ctx = canvas.getContext('2d');
        if(ctx) {
            const grad = ctx.createRadialGradient(16, 16, 0, 16, 16, 16);
            grad.addColorStop(0, 'rgba(255, 255, 255, 1)');
            grad.addColorStop(0.2, 'rgba(200, 255, 255, 0.8)');
            grad.addColorStop(0.5, 'rgba(0, 255, 255, 0.2)');
            grad.addColorStop(1, 'rgba(0, 0, 0, 0)');
            ctx.fillStyle = grad;
            ctx.fillRect(0, 0, 32, 32);
        }
        return new THREE.CanvasTexture(canvas);
    };

    const material = new THREE.PointsMaterial({
        size: 0.35,
        map: getTexture(),
        transparent: true,
        opacity: 0.9,
        vertexColors: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
    });

    const particles = new THREE.Points(geometry, material);
    scene.add(particles);

    const coreGeo = new THREE.IcosahedronGeometry(1.5, 0);
    const coreMat = new THREE.MeshPhysicalMaterial({
        color: 0x00ffff,
        emissive: 0x0044ff,
        emissiveIntensity: 2,
        roughness: 0.1,
        metalness: 0.9,
        transparent: true,
        opacity: 0.9,
        transmission: 0.2,
        thickness: 1.0,
    });
    const coreMesh = new THREE.Mesh(coreGeo, coreMat);
    scene.add(coreMesh);

    const haloGeo = new THREE.PlaneGeometry(15, 15);
    const haloMat = new THREE.MeshBasicMaterial({
        map: getTexture(),
        color: 0x00ffff,
        transparent: true,
        opacity: 0.4,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide
    });
    const haloMesh = new THREE.Mesh(haloGeo, haloMat);
    scene.add(haloMesh);

    const loader = new GLTFLoader();
    loader.load('3834385f-f829-4a28-8dfd-e9125e9cb138.glb', (gltf) => {
        const meshes: THREE.Mesh[] = [];
        gltf.scene.traverse((child) => {
            if ((child as THREE.Mesh).isMesh) {
                meshes.push(child as THREE.Mesh);
            }
        });

        if (meshes.length > 0) {
            const mesh = meshes[0];
            const sampler = new MeshSurfaceSampler(mesh).build();
            const tempPos = new THREE.Vector3();
            const tempNormal = new THREE.Vector3();
            const SCALE = 15.0;

            for (let i = 0; i < PARTICLE_COUNT; i++) {
                sampler.sample(tempPos, tempNormal);
                targets[i * 3] = tempPos.x * SCALE;
                targets[i * 3 + 1] = tempPos.y * SCALE;
                targets[i * 3 + 2] = tempPos.z * SCALE;

                const dist = tempPos.length();
                const a = Math.min(1, dist * 2 + 0.2); 
                const c = color1.clone().lerp(color2, a);
                colors[i * 3] = c.r;
                colors[i * 3 + 1] = c.g;
                colors[i * 3 + 2] = c.b;
            }
            geometry.attributes.color.needsUpdate = true;
        }
    }, undefined, console.error);

    const mouse = new THREE.Vector2();
    const raycaster = new THREE.Raycaster();
    const plane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
    const mouseParams = { active: false };

    const handleMouseMove = (event: MouseEvent) => {
        const rect = mountRef.current?.getBoundingClientRect();
        if (!rect) return;
        mouse.x = ((event.clientX - rect.left) / width) * 2 - 1;
        mouse.y = -((event.clientY - rect.top) / height) * 2 + 1;
        mouseParams.active = true;
    };

    const clock = new THREE.Clock();
    let frameId: number;

    const animate = () => {
        frameId = requestAnimationFrame(animate);
        const time = clock.getElapsedTime();

        controls.update();
        raycaster.setFromCamera(mouse, camera);
        const intersect = new THREE.Vector3();
        raycaster.ray.intersectPlane(plane, intersect);

        for (let i = 0; i < PARTICLE_COUNT; i++) {
            const ix = i * 3;
            const iy = i * 3 + 1;
            const iz = i * 3 + 2;

            let px = positions[ix];
            let py = positions[iy];
            let pz = positions[iz];

            const tx = targets[ix];
            const ty = targets[iy];
            const tz = targets[iz];

            let vx = velocities[ix];
            let vy = velocities[iy];
            let vz = velocities[iz];

            vx += (tx - px) * 0.03;
            vy += (ty - py) * 0.03;
            vz += (tz - pz) * 0.03;

            const rnd = randomness[i];
            const nAmp = 0.02;
            vx += Math.sin(time * 2 + py * 0.5 + rnd * 10) * nAmp;
            vy += Math.cos(time * 1.5 + px * 0.5 + rnd * 10) * nAmp;
            vz += Math.sin(time * 2.2 + pz * 0.5 + rnd * 10) * nAmp;

            if (mouseParams.active) {
                const dx = px - intersect.x;
                const dy = py - intersect.y;
                const dz = pz - intersect.z;
                const distSq = dx*dx + dy*dy + dz*dz;
                const radSq = 600.0;
                if (distSq < radSq) {
                    const f = (radSq - distSq) / radSq;
                    vx += dx * f * 1.0;
                    vy += dy * f * 1.0;
                    vz += dz * f * 1.0;
                }
            }

            vx *= 0.92;
            vy *= 0.92;
            vz *= 0.92;

            positions[ix] += vx;
            positions[iy] += vy;
            positions[iz] += vz;

            velocities[ix] = vx;
            velocities[iy] = vy;
            velocities[iz] = vz;
        }

        geometry.attributes.position.needsUpdate = true;

        const pulse = 1 + Math.sin(time * 2.5) * 0.1;
        coreMesh.scale.set(pulse, pulse, pulse);
        coreMesh.rotation.y += 0.01;
        coreMesh.rotation.z += 0.005;

        haloMesh.lookAt(camera.position);

        renderer.render(scene, camera);
    };

    window.addEventListener('mousemove', handleMouseMove);
    animate();

    return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        cancelAnimationFrame(frameId);
        if (mountRef.current && renderer.domElement) {
             mountRef.current.removeChild(renderer.domElement);
        }
        controls.dispose();
        geometry.dispose();
        material.dispose();
        renderer.dispose();
    };
  }, [width, height]);

  return <div ref={mountRef} />;
};

export default SceneQuantum;

import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

interface SceneProps {
  width: number;
  height: number;
}

const SceneNeural: React.FC<SceneProps> = ({ width, height }) => {
  const mountRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!mountRef.current) return;

    // --- SETUP ---
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x000010, 0.02);

    const camera = new THREE.PerspectiveCamera(75, width / height, 0.1, 1000);
    camera.position.set(0, 0, 50);

    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    mountRef.current.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.autoRotate = true;
    controls.autoRotateSpeed = 0.2;

    // --- NETWORK GENERATION ---
    const NODES_COUNT = 200;
    const MAX_DIST = 15;

    // Data Storage
    const nodePositions: THREE.Vector3[] = [];

    // Geometry for InstancedMesh
    const nodeGeo = new THREE.SphereGeometry(0.5, 8, 8);
    const nodeMat = new THREE.MeshBasicMaterial({ color: 0x0088ff });
    const nodesMesh = new THREE.InstancedMesh(nodeGeo, nodeMat, NODES_COUNT);
    // Dynamic color support for instances requires custom handling or just setting color prop per instance
    // InstancedMesh setColorAt works efficiently.

    const dummy = new THREE.Object3D();
    const baseColor = new THREE.Color(0x0088ff);
    const highlightColor = new THREE.Color(0xffaa00);

    for(let i=0; i<NODES_COUNT; i++) {
        const r = 25 * Math.cbrt(Math.random()); 
        const theta = Math.random() * Math.PI * 2;
        const phi = Math.acos(2 * Math.random() - 1);

        const x = r * Math.sin(phi) * Math.cos(theta);
        const y = r * Math.sin(phi) * Math.sin(theta);
        const z = r * Math.cos(phi);

        const v = new THREE.Vector3(x, y, z);
        nodePositions.push(v);

        dummy.position.copy(v);
        dummy.updateMatrix();
        nodesMesh.setMatrixAt(i, dummy.matrix);
        nodesMesh.setColorAt(i, baseColor);
    }
    scene.add(nodesMesh);

    // Edges
    interface Edge {
        start: THREE.Vector3;
        end: THREE.Vector3;
        length: number;
    }
    const edges: Edge[] = [];
    const points: THREE.Vector3[] = [];

    for(let i=0; i<NODES_COUNT; i++) {
        for(let j=i+1; j<NODES_COUNT; j++) {
            const d = nodePositions[i].distanceTo(nodePositions[j]);
            if(d < MAX_DIST) {
                edges.push({ start: nodePositions[i], end: nodePositions[j], length: d });
                points.push(nodePositions[i]);
                points.push(nodePositions[j]);
            }
        }
    }

    const lineGeo = new THREE.BufferGeometry().setFromPoints(points);
    const lineMat = new THREE.LineBasicMaterial({ color: 0x004488, transparent: true, opacity: 0.1 });
    const lines = new THREE.LineSegments(lineGeo, lineMat);
    scene.add(lines);

    // Signals
    const SIGNAL_COUNT = 1000;
    const sigGeo = new THREE.BufferGeometry();
    const sigPos = new Float32Array(SIGNAL_COUNT * 3);
    const sigColors = new Float32Array(SIGNAL_COUNT * 3);
    const sigData = new Float32Array(SIGNAL_COUNT * 2); // [edgeIndex, progress]

    const cSig = new THREE.Color(0xffffff); 

    for(let i=0; i<SIGNAL_COUNT; i++) {
        sigData[i*2] = Math.floor(Math.random() * edges.length);
        sigData[i*2+1] = Math.random(); 

        sigColors[i*3] = cSig.r;
        sigColors[i*3+1] = cSig.g;
        sigColors[i*3+2] = cSig.b;
    }

    sigGeo.setAttribute('position', new THREE.BufferAttribute(sigPos, 3));
    sigGeo.setAttribute('color', new THREE.BufferAttribute(sigColors, 3));

    const sigMat = new THREE.PointsMaterial({
        size: 0.6,
        color: 0xffffff,
        transparent: true,
        opacity: 0.8,
        vertexColors: true,
        blending: THREE.AdditiveBlending
    });
    const signals = new THREE.Points(sigGeo, sigMat);
    scene.add(signals);

    // --- MOUSE ---
    const mouse = new THREE.Vector2();
    const raycaster = new THREE.Raycaster();
    const mouseParams = { active: false };

    // We also need a plane to intersect for 3D cursor position
    // Since it's a volumetric cloud, we can try to find the closest node or just a virtual plane at depth 0
    // Better: Find closest node to ray.

    const handleMouseMove = (event: MouseEvent) => {
        const rect = mountRef.current?.getBoundingClientRect();
        if (!rect) return;
        mouse.x = ((event.clientX - rect.left) / width) * 2 - 1;
        mouse.y = -((event.clientY - rect.top) / height) * 2 + 1;
        mouseParams.active = true;
    };

    // --- ANIMATION ---
    let frameId: number;
    const animate = () => {
        frameId = requestAnimationFrame(animate);
        controls.update();

        // Interaction Logic
        raycaster.setFromCamera(mouse, camera);

        let targetNodeIndex = -1;
        let closestDist = Infinity;
        let mouse3D = new THREE.Vector3(); // Approx position

        // 1. Find Closest Node to Ray
        // Simple scan (ok for 200 nodes)
        if (mouseParams.active) {
            // Unproject mouse to get ray direction
            // Calculate distance from point to line for each node
            const ray = raycaster.ray;

            for(let i=0; i<NODES_COUNT; i++) {
                const pos = nodePositions[i];
                // Distance from point to ray
                const distSq = ray.distanceSqToPoint(pos);
                if (distSq < 2.0 && distSq < closestDist) { // Threshold
                    closestDist = distSq;
                    targetNodeIndex = i;
                    mouse3D.copy(pos); // Set 3D target to this node
                }
            }
        }

        // 2. Update Instanced Mesh Colors
        for(let i=0; i<NODES_COUNT; i++) {
            if (i === targetNodeIndex) {
                 nodesMesh.setColorAt(i, highlightColor);
                 // Scale up effect? requires getting matrix, scaling, setting matrix. 
                 // Let's stick to color for performance.
            } else {
                 nodesMesh.setColorAt(i, baseColor);
            }
        }
        if (nodesMesh.instanceColor) nodesMesh.instanceColor.needsUpdate = true;


        // 3. Update Signals
        const sPos = sigGeo.attributes.position.array as Float32Array;

        for(let i=0; i<SIGNAL_COUNT; i++) {
            let edgeIdx = sigData[i*2];
            let progress = sigData[i*2+1];

            // Speed
            let speed = 0.01;

            // Interaction: If target node exists, signals rush towards it
            // We check if current edge is connected to target node
            if (targetNodeIndex !== -1) {
                const edge = edges[edgeIdx];
                const startNode = edge.start;
                const endNode = edge.end;
                const targetPos = nodePositions[targetNodeIndex];

                // Simple check: is this edge connected to the target?
                // Or: are we getting closer to target?
                const distStart = startNode.distanceTo(targetPos);
                const distEnd = endNode.distanceTo(targetPos);

                // If this edge gets us closer, speed up
                if (distEnd < distStart || distStart < distEnd) {
                     speed = 0.03; // Rush
                }
            }

            // Move
            progress += speed;
            if(progress >= 1) {
                progress = 0;
                edgeIdx = Math.floor(Math.random() * edges.length);
                sigData[i*2] = edgeIdx;
            } else {
                sigData[i*2+1] = progress;
            }

            const edge = edges[edgeIdx];
            const x = edge.start.x + (edge.end.x - edge.start.x) * progress;
            const y = edge.start.y + (edge.end.y - edge.start.y) * progress;
            const z = edge.start.z + (edge.end.z - edge.start.z) * progress;

            sPos[i*3] = x;
            sPos[i*3+1] = y;
            sPos[i*3+2] = z;
        }

        sigGeo.attributes.position.needsUpdate = true;

        renderer.render(scene, camera);
    };

    window.addEventListener('mousemove', handleMouseMove);
    animate();

    return () => {
        window.removeEventListener('mousemove', handleMouseMove);
        cancelAnimationFrame(frameId);
        if (mountRef.current && renderer.domElement) {
             mountRef.current.removeChild(renderer.domElement);
        }
        controls.dispose();
    };
  }, [width, height]);

  return <div ref={mountRef} />;
};

export default SceneNeural;
